update public.products set description='Mumuyi white yam is a Nigerian white-yam variety suitable for boiling, frying, roasting, yam porridge and pounded yam.', handling_protocols=array['Handle carefully and avoid cuts or heavy bruising.','Do not wash before storage; keep the tuber surface dry.','Use damaged tubers first and inspect stored yams regularly.']::text[], storage_tips=array['Store in a shaded, dry and well-ventilated place away from damp floors.','Do not seal in airtight plastic or leave in direct sunlight.','For dependable household quality, use within about 2–4 weeks.','Use sprouting but otherwise sound yams sooner and discard tubers with spreading rot or extensive mold.']::text[] where name like 'White Yam (Mumuyi) - %' and category_id=(select id from public.product_categories where name='Tubers & Legumes');;
